package it.trentosmartmountain.app.ui.screens.registraimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.FiberManualRecordimport androidx.compose.runtime.Composableimport androidx.compose.ui.Modifierimport androidx.compose.ui.res.stringResourceimport it.trentosmartmountain.app.R/** * FAB centrale per avviare la registrazione GPS (stato IDLE), con glow arancione pulsante. */@Composablefun RegistraRecFab(  onClick: () -> Unit,  modifier: Modifier = Modifier,) {  RegistraGlowFab(    onClick = onClick,    icon = Icons.Filled.FiberManualRecord,    contentDescription = stringResource(R.string.registra_start_tracking_cd),    modifier = modifier,    fabSize = RegistraLayout.primaryFabSize,    iconSize = RegistraLayout.primaryFabIconSize,  )}